-- Hidden State — first-run data.
--
-- Run AFTER schema.sql:
--   npx wrangler d1 execute hiddenstate --remote --file=./seed.sql
--
-- Safe to re-run: every insert ignores rows that already exist.

-- The boss account. The password is not written here — only its PBKDF2 hash.
INSERT OR IGNORE INTO team (username, role, display_name, password_hash, salt, active, created_at, created_by)
VALUES ('hiddenstateboss_stephannojunior', 'BOSS', 'Stephanno Jr.', 'f3a1f356cff8187e692a26f60b413d6bcff662cb3197c670e25637ee04bdc741', 'b4080d83b73a9f0aa5dd26406a0ac692', 1, datetime('now'), 'setup');

-- The December night. Doors shut at 6am the following morning, not midnight,
-- so anyone arriving late is not refused by their own pass.
INSERT OR IGNORE INTO parties (id, name, date_label, venue, doors_close_at, minimum_age, rotating, created_at, created_by)
VALUES ('dec13', '13.12.2026', '13 December 2026', NULL, '2026-12-14T06:00:00+02:00', 16, 1, datetime('now'), 'setup');

